import { rewriteImageUrl } from "./util";

export const ChatVideo = ({ src, style }: { src: string; style?: React.CSSProperties }) => {
    if (src.includes("youtube")) {
        const id = src.split("v=")[1].split("&")[0];
        return (
            <iframe
                style={style}
                width="560"
                height="315"
                src={`https://www.youtube.com/embed/${id}`}
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                allowFullScreen
            ></iframe>
        );
    }
    return <video style={style} src={rewriteImageUrl(src)} controls />;
};
